use thinkthen::{Answer, Engine, Question};
let tt = Engine::from_env()?;

// the outage first at 0.94, the quote second at 0.93
let inbox = ["Newsletter: our autumn catalog is here",
    "Our checkout page is down and customers cannot pay",
    "The client needs the signed quote by 5 pm today.",
    "Reminder: your invoice is due in 30 days"];
let ranked = tt.rank("Does this need an answer today?", &inbox)?;
for one in ranked.iter().take(2) {
    println!("{} {}", one.probability, inbox[one.index]);
}
